body {
  font-family: "MyCustomWebFont", Arial, sans-serif;
  font-size: 16px;
  font-size-adjust: 0.58; /* Adjust based on the x-height of MyCustomWebFont */
}

/* Example with different fallback adjustment */
h1 {
  font-family: "HeadingFont", Georgia, serif;
  font-size: 2.5em;
  font-size-adjust: 0.50; /* Adjust based on the x-height of HeadingFont */
}
